class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  int _pestanaActual = 0;
  bool _agenteActivo = false;
  final List<StreamSubscription<WatchEvent>> _watchersSubs = [];
  Timer? _pollingCarpetaTimer;
  Timer? _syncTimer;

  // Cliente HTTP persistente (Keep-Alive) para ahorrar ~1.5s de handshake SSL en cada foto
  final http.Client _httpClient = http.Client();

  final List<EjercicioResuelto> _historial = [];
  final List<EjercicioResuelto> _colaPendientes = [];
  bool _procesandoCola = false;
  bool _cargandoPpts = false;

  final List<PptCompartido> _pptsDeLaSala = [];
  final List<PptCompartido> _pptsActivos = [];

  final Set<String> _idsEliminados = {};
  final Set<String> _archivosYaVistos = {};

  final String _rutaCarpeta = '/storage/emulated/0/Pictures/SayCheese';
  final List<String> _rutasVigiladas = [
    '/storage/emulated/0/Pictures/SayCheese',
    '/storage/emulated/0/DCIM/SayCheese',
    '/storage/emulated/0/SayCheese',
    '/storage/emulated/0/Download/SayCheese',
  ];

  final String _rutaRespaldoFijo =
      '/storage/emulated/0/Pictures/SayCheese/.saycheese_historial_v15.json';

  String _apiKey = const String.fromEnvironment(
    'GEMINI_API_KEY',
    defaultValue: '',
  );

  // Por defecto usamos gemini-3-flash-preview para velocidad instantanea (o Pro si el usuario lo cambia)
  String _modeloSeleccionado = 'gemini-3-flash-preview';
  final List<String> _modelosDisponibles = [
    'gemini-3-flash-preview',
    'gemini-2.5-flash',
    'gemini-3.1-pro-preview',
    'gemini-2.5-pro',
    'gemini-2.0-flash',
  ];

  final Set<String> _modelosSinCuotaEnSesion = {};
  // Cache del texto combinado de los PPTs activos para no reconstruirlo en cada foto
  String _cacheContextoPpts = '';

  String _codigoSala = '';
  String _aliasUsuario = 'felipe';
  bool _sincronizando = false;
  String _estadoSala = 'Conectado';

  @override
  void initState() {
    super.initState();
    _inicializarTodo();
  }

  Future<void> _inicializarTodo() async {
    await _cargarDatosLocales();
    await _iniciarAgente();
    _syncTimer = Timer.periodic(const Duration(seconds: 6), (_) {
      if (_codigoSala.isNotEmpty && !_procesandoCola) {
        _sincronizarSalaCompartida(silencioso: true);
      }
    });
  }

  String _limpiarCodigoSala(String raw) {
    return raw
        .trim()
        .toUpperCase()
        .replaceAll(RegExp(r'\s+'), '')
        .replaceAll(RegExp(r'[^A-Z0-9-]'), '');
  }

  String get _etiquetaPptsActivos {
    if (_pptsActivos.isEmpty) return '';
    return _pptsActivos.map((p) => p.nombre).join(' + ');
  }

  void _actualizarCacheContextoPpts() {
    if (_pptsActivos.isEmpty) {
      _cacheContextoPpts = '';
      return;
    }
    final sb = StringBuffer();
    for (int i = 0; i < _pptsActivos.length; i++) {
      final p = _pptsActivos[i];
      if (p.textoExtraido.isNotEmpty) {
        sb.writeln(
            '=== PRESENTACION PPT #${i + 1}: ${p.nombre} (Completo, sin cortes) ===');
        sb.writeln(p.textoExtraido);
        sb.writeln();
      }
    }
    _cacheContextoPpts = sb.toString().trim();
  }

  Future<void> _cargarDatosLocales() async {
    final prefs = await SharedPreferences.getInstance();
    final savedKey = prefs.getString('gemini_api_key');
    if (savedKey != null && savedKey.isNotEmpty) {
      _apiKey = savedKey;
    }

    final savedModel = prefs.getString('gemini_model');
    if (savedModel != null && savedModel.isNotEmpty) {
      if (!_modelosDisponibles.contains(savedModel)) {
        _modelosDisponibles.insert(0, savedModel);
      }
      _modeloSeleccionado = savedModel;
    }

    _codigoSala = _limpiarCodigoSala(prefs.getString('sala_compartida') ?? '');
    _aliasUsuario = prefs.getString('alias_usuario') ?? 'felipe';

    final eliminadosGuardados = prefs.getStringList('ids_eliminados_v15') ??
        prefs.getStringList('ids_eliminados_v14') ??
        [];
    _idsEliminados
      ..clear()
      ..addAll(eliminadosGuardados);

    final vistosGuardados = prefs.getStringList('archivos_vistos_v15') ??
        prefs.getStringList('archivos_vistos_v14') ??
        [];
    _archivosYaVistos
      ..clear()
      ..addAll(vistosGuardados);

    final pptsSalaJson =
        prefs.getString('ppts_sala_v15') ?? prefs.getString('ppts_sala_v14');
    if (pptsSalaJson != null && pptsSalaJson.isNotEmpty) {
      try {
        final List rawPpts = jsonDecode(pptsSalaJson);
        _pptsDeLaSala
          ..clear()
          ..addAll(rawPpts
              .map((e) => PptCompartido.fromJson(e as Map<String, dynamic>)));
      } catch (_) {}
    }

    final pptsActivosJson = prefs.getString('ppts_activos_v15') ??
        prefs.getString('ppts_activos_v14');
    if (pptsActivosJson != null && pptsActivosJson.isNotEmpty) {
      try {
        final List rawAct = jsonDecode(pptsActivosJson);
        _pptsActivos
          ..clear()
          ..addAll(rawAct
              .map((e) => PptCompartido.fromJson(e as Map<String, dynamic>))
              .take(2));
        _actualizarCacheContextoPpts();
      } catch (_) {}
    }

    List<EjercicioResuelto> cargados = [];

    try {
      final rawUnificado = prefs.getString('historial_json_completo_v15') ??
          prefs.getString('historial_json_completo_v14') ??
          prefs.getString('historial_json_completo_v13');
      if (rawUnificado != null && rawUnificado.isNotEmpty) {
        final List listaRaw = jsonDecode(rawUnificado);
        cargados = listaRaw
            .map((e) => EjercicioResuelto.fromJson(e as Map<String, dynamic>))
            .where((e) => !_idsEliminados.contains(e.id))
            .toList();
      }
    } catch (_) {}

    if (cargados.isEmpty) {
      try {
        final file = File(_rutaRespaldoFijo);
        if (await file.exists()) {
          final contenido = await file.readAsString();
          if (contenido.isNotEmpty) {
            final List listaRaw = jsonDecode(contenido);
            cargados = listaRaw
                .map((e) =>
                    EjercicioResuelto.fromJson(e as Map<String, dynamic>))
                .where((e) => !_idsEliminados.contains(e.id))
                .toList();
          }
        }
      } catch (_) {}
    }

    for (final c in cargados) {
      if (c.rutaImagen != null) {
        _archivosYaVistos.add(c.rutaImagen!);
      }
      if (c.procesando) {
        c.estadoCola = 'En cola';
        _colaPendientes.add(c);
      }
    }

    if (mounted) {
      setState(() {
        _historial
          ..clear()
          ..addAll(cargados);
      });
    }

    if (_colaPendientes.isNotEmpty) {
      _ejecutarColaSecuencial();
    }

    if (_codigoSala.isNotEmpty) {
      _sincronizarSalaCompartida(silencioso: true);
    }
  }

  Future<void> _guardarHistorialLocal() async {
    final listaMap = _historial.map((e) => e.toJson()).toList();
    final jsonCompleto = jsonEncode(listaMap);
    final jsonPptsSala =
        jsonEncode(_pptsDeLaSala.map((p) => p.toJson()).toList());
    final jsonPptsActivos =
        jsonEncode(_pptsActivos.map((p) => p.toJson()).toList());

    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('historial_json_completo_v15', jsonCompleto);
      await prefs.setString('historial_json_completo_v14', jsonCompleto);
      await prefs.setString('ppts_sala_v15', jsonPptsSala);
      await prefs.setString('ppts_activos_v15', jsonPptsActivos);
      await prefs.setStringList('ids_eliminados_v15', _idsEliminados.toList());
      await prefs.setStringList(
          'archivos_vistos_v15', _archivosYaVistos.toList());
    } catch (_) {}

    try {
      final file = File(_rutaRespaldoFijo);
      await file.writeAsString(jsonCompleto, flush: true);
    } catch (_) {}
  }

  Future<void> _eliminarSolucion(EjercicioResuelto item) async {
    setState(() {
      _idsEliminados.add(item.id);
      _colaPendientes.removeWhere((e) => e.id == item.id);
      _historial.removeWhere((e) => e.id == item.id);
    });
    await _guardarHistorialLocal();
    await _publicarEventoEnSala({
      'tipo': 'eliminar_solucion',
      'id': item.id,
      'emisor': _aliasUsuario,
    });
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Hoja eliminada.'),
          duration: Duration(seconds: 2),
        ),
      );
    }
  }

  Future<void> _confirmarBorrarTodasLasSoluciones() async {
    final confirmar = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Vaciar Solucionario'),
        content: const Text(
            '¿Seguro que quieres eliminar todas las soluciones guardadas?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('Cancelar'),
          ),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: Colors.redAccent),
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Eliminar Todas'),
          ),
        ],
      ),
    );

    if (confirmar == true) {
      setState(() {
        for (final e in _historial) {
          _idsEliminados.add(e.id);
        }
        _colaPendientes.clear();
        _historial.clear();
      });
      await _guardarHistorialLocal();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
              content: Text('Todas las soluciones fueron eliminadas.')),
        );
      }
    }
  }

  // Guarda el 100% del texto de todas las diapositivas del PPT SIN CORTAR NINGUN ELEMENTO
  Future<void> _agregarOActivarPpt({
    required String nombre,
    required String textoExtraido,
    required String autor,
    String? base64Pdf,
    int? slotForzado,
    bool compartirEnSala = true,
  }) async {
    final nuevoPpt = PptCompartido(
      id: '${nombre}_$autor',
      nombre: nombre,
      autor: autor,
      textoExtraido: textoExtraido,
      base64Pdf: base64Pdf,
      fecha: DateTime.now(),
    );

    if (mounted) {
      setState(() {
        _pptsDeLaSala.removeWhere((p) => p.nombre == nombre);
        _pptsDeLaSala.insert(0, nuevoPpt);

        final idxExistente =
            _pptsActivos.indexWhere((p) => p.nombre == nombre);
        if (idxExistente != -1) {
          _pptsActivos[idxExistente] = nuevoPpt;
        } else if (slotForzado != null &&
            slotForzado >= 0 &&
            slotForzado < _pptsActivos.length) {
          _pptsActivos[slotForzado] = nuevoPpt;
        } else if (_pptsActivos.length < 2) {
          _pptsActivos.add(nuevoPpt);
        } else {
          _pptsActivos[1] = nuevoPpt;
        }
        _actualizarCacheContextoPpts();
      });
    }
    await _guardarHistorialLocal();

    if (compartirEnSala &&
        _codigoSala.isNotEmpty &&
        textoExtraido.isNotEmpty) {
      unawaited(_publicarPptEnSala(nuevoPpt));
    }
  }

  Future<void> _quitarPptPorIndice(int index) async {
    if (index < 0 || index >= _pptsActivos.length) return;
    final quitado = _pptsActivos[index].nombre;
    setState(() {
      _pptsActivos.removeAt(index);
      _actualizarCacheContextoPpts();
    });
    await _guardarHistorialLocal();
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('PPT quitado: $quitado')),
      );
    }
  }

  Future<void> _quitarTodosLosPpts() async {
    setState(() {
      _pptsActivos.clear();
      _actualizarCacheContextoPpts();
    });
    await _guardarHistorialLocal();
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
            content: Text(
                'Ambos PPTs desvinculados. Ahora Gemini respondera sin material externo.')),
      );
    }
  }

  Future<void> _procesarBytesDeArchivoSubido(
      String nombre, List<int> bytes, String b64Data,
      {int? slotForzado}) async {
    final ext = nombre.toLowerCase();
    if (ext.endsWith('.pptx')) {
      final textoFinal =
          await compute(extraerTextoPptxSinCortesEnIsolate, bytes);
      if (textoFinal.isEmpty) {
        throw Exception('No se encontro texto legible dentro del PPTX.');
      }
      await _agregarOActivarPpt(
        nombre: nombre,
        textoExtraido: textoFinal,
        autor: _aliasUsuario,
        slotForzado: slotForzado,
      );
    } else if (ext.endsWith('.pdf')) {
      await _agregarOActivarPpt(
        nombre: nombre,
        textoExtraido: '[Documento PDF completo cargado por $_aliasUsuario: $nombre]',
        autor: _aliasUsuario,
        base64Pdf: b64Data,
        slotForzado: slotForzado,
      );
    } else {
      String texto = '';
      try {
        texto = await compute(extraerTextoPptxSinCortesEnIsolate, bytes);
      } catch (_) {
        texto = utf8.decode(bytes, allowMalformed: true);
      }
      await _agregarOActivarPpt(
        nombre: nombre,
        textoExtraido: texto,
        autor: _aliasUsuario,
        slotForzado: slotForzado,
      );
    }
  }

  Future<void> _mostrarExploradorInternoDeArchivos(
      {required bool paraFoto, int? slotForzado}) async {
    await [
      Permission.photos,
      Permission.storage,
      Permission.manageExternalStorage,
    ].request();

    final archivos = paraFoto
        ? await _buscarFotosEnTelefono()
        : await _buscarArchivosPptEnTelefono();
    final Set<String> seleccionados = {};

    if (!mounted) return;
    showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setModalState) => AlertDialog(
          title: Text(paraFoto
              ? 'Elegir Fotos (Se agregan a la Cola)'
              : 'Selecciona 1 o 2 PPTs a la vez'),
          content: SizedBox(
            width: double.maxFinite,
            height: 340,
            child: archivos.isEmpty
                ? Center(
                    child: Text(paraFoto
                        ? 'No se encontraron fotos en SayCheese, Camara o Descargas.'
                        : 'No se encontraron archivos .pptx o .pdf en Descargas o Documentos. Usa los enlaces de Google Drive arriba.'))
                : ListView.builder(
                    itemCount: archivos.length,
                    itemBuilder: (_, i) {
                      final f = archivos[i];
                      final name = f.path.split('/').last;
                      final marcado = seleccionados.contains(f.path);
                      return Card(
                        color: marcado
                            ? Colors.deepPurple.withOpacity(0.35)
                            : null,
                        margin: const EdgeInsets.only(bottom: 6),
                        child: ListTile(
                          leading: Icon(
                              paraFoto
                                  ? Icons.image
                                  : (marcado
                                      ? Icons.check_box
                                      : Icons.check_box_outline_blank),
                              color: marcado
                                  ? Colors.greenAccent
                                  : Colors.amberAccent),
                          title: Text(name,
                              maxLines: 1, overflow: TextOverflow.ellipsis),
                          subtitle: Text(f.parent.path,
                              style: const TextStyle(fontSize: 10)),
                          onTap: () {
                            if (paraFoto) {
                              Navigator.pop(ctx);
                              _archivosYaVistos.add(f.path);
                              _encolarNuevaFoto(f, esManual: true);
                            } else {
                              setModalState(() {
                                if (marcado) {
                                  seleccionados.remove(f.path);
                                } else {
                                  if (seleccionados.length >= 2) {
                                    seleccionados.remove(seleccionados.first);
                                  }
                                  seleccionados.add(f.path);
                                }
                              });
                            }
                          },
                        ),
                      );
                    },
                  ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('Cerrar'),
            ),
            if (!paraFoto && archivos.isNotEmpty)
              FilledButton.icon(
