  Future<void> _ejecutarColaSecuencial() async {
    if (_procesandoCola) return;
    _procesandoCola = true;

    try {
      while (_colaPendientes.isNotEmpty) {
        final actual = _colaPendientes.first;
        if (_idsEliminados.contains(actual.id) || actual.rutaImagen == null) {
          _colaPendientes.removeAt(0);
          continue;
        }

        if (mounted) {
          setState(() {
            actual.procesando = true;
            actual.estadoCola = 'Resolviendo ahora...';
          });
        }

        final archivoFoto = File(actual.rutaImagen!);
        for (int w = 0; w < 3; w++) {
          if (await archivoFoto.exists() && await archivoFoto.length() > 1024) {
            break;
          }
          await Future.delayed(const Duration(milliseconds: 250));
        }

        try {
          final resultado = await _llamarGeminiUltrarrapidoSinCortes(
            archivoFoto,
            actual.modeloUsado,
          );
          if (mounted) {
            setState(() {
              actual.solucion = _limpiarRespuestaMarkdown(resultado['texto']!);
              actual.modeloUsado = resultado['modeloFinal']!;
              actual.procesando = false;
              actual.estadoCola = 'Listo';
            });
          }
          await _guardarHistorialLocal();
          unawaited(_publicarSolucionIndividualEnSala(actual));
        } catch (e) {
          if (mounted) {
            setState(() {
              actual.solucion = 'Error al resolver: $e';
              actual.procesando = false;
              actual.estadoCola = 'Error';
            });
          }
          await _guardarHistorialLocal();
        }

        _colaPendientes.removeWhere((e) => e.id == actual.id);
        if (mounted) setState(() {});
      }
    } finally {
      _procesandoCola = false;
    }
  }

  String _limpiarRespuestaMarkdown(String raw) {
    var limpio = raw.replaceAll('```markdown', '').replaceAll('```', '');
    final lineas = limpio.split('\n');
    final procesadas = lineas.map((linea) {
      if (linea.startsWith('    ') &&
          !linea.trimLeft().startsWith('*') &&
          !linea.trimLeft().startsWith('-') &&
          !RegExp(r'^\d+\.').hasMatch(linea.trimLeft())) {
        return linea.trimLeft();
      }
      return linea;
    }).toList();
    return procesadas.join('\n').trim();
  }

  Future<bool> _asegurarRedDespierta() async {
    for (int i = 0; i < 10; i++) {
      try {
        final res =
            await InternetAddress.lookup('generativelanguage.googleapis.com')
                .timeout(const Duration(seconds: 2));
        if (res.isNotEmpty && res.first.rawAddress.isNotEmpty) {
          return true;
        }
      } catch (_) {}
      await Future.delayed(const Duration(milliseconds: 600));
    }
    return false;
  }

  // Motor v15:
  // 1. Comprime la foto a JPEG ligero (~110 KB) en un Isolate para que suba en 0.2s incluso cuando hay 2 PPTs adjuntos.
  // 2. Envia el 100% de los 2 PPTs sin recortarles ninguna diapositiva.
  // 3. Configura maxOutputTokens: 8192 para que NINGUNA respuesta o ejercicio quede cortado a la mitad.
  // 4. Usa thinkingBudget ligero (512 tokens) para que responda en menos de la mitad del tiempo.
  Future<Map<String, String>> _llamarGeminiUltrarrapidoSinCortes(
      File imagen, String modeloElegido) async {
    final keyLimpia = _apiKey.trim();
    if (keyLimpia.isEmpty) {
      throw Exception('Configura tu clave en el icono de engranaje superior.');
    }

    final bytesOriginales = await imagen.readAsBytes();
    final base64Image =
        await compute(comprimirImagenJpegBase64EnIsolate, bytesOriginales);
    final modInicial = modeloElegido.trim();

    String promptTexto =
        "Resuelve TODOS los ejercicios de esta imagen de principio a fin, sin omitir ni cortar ningun punto o pregunta. Ve directo al desarrollo y a la respuesta final en negrita con formato Markdown claro (NUNCA uses bloques de codigo ni sangrias de 4 espacios).";

    if (_cacheContextoPpts.isNotEmpty) {
      promptTexto +=
          "\n\nUSA ESTRICTAMENTE LA SIGUIENTE INFORMACION COMPLETA DE LOS PPT CARGADOS PARA RESPONDER:\n$_cacheContextoPpts";
    }

    final List<Map<String, dynamic>> parts = [
      {"text": promptTexto},
      {
        "inline_data": {
          "mime_type": "image/jpeg",
          "data": base64Image,
        }
      }
    ];

    for (final p in _pptsActivos) {
      if (p.base64Pdf != null && p.base64Pdf!.isNotEmpty) {
        parts.add({
          "inline_data": {
            "mime_type": "application/pdf",
            "data": p.base64Pdf,
          }
        });
      }
    }

    final List<String> candidatos = [];
    if (!_modelosSinCuotaEnSesion.contains(modInicial)) {
      candidatos.add(modInicial);
    }
    for (final respaldoRapido in [
      'gemini-3-flash-preview',
      'gemini-2.5-flash',
      'gemini-2.0-flash',
    ]) {
      if (!candidatos.contains(respaldoRapido) &&
          !_modelosSinCuotaEnSesion.contains(respaldoRapido)) {
        candidatos.add(respaldoRapido);
      }
    }
    if (candidatos.isEmpty) {
      candidatos.addAll(['gemini-3-flash-preview', 'gemini-2.0-flash']);
    }

    String ultimoDetalleError = '';

    for (final modCandidato in candidatos) {
      final Map<String, dynamic> payload = {
        "contents": [
          {"parts": parts}
        ],
        "generationConfig": {
          "maxOutputTokens": 8192,
          "temperature": 0.2,
          if (modCandidato.contains('2.5'))
            "thinkingConfig": {"thinkingBudget": 512}
        }
      };

      final url = Uri.parse(
        'https://generativelanguage.googleapis.com/v1beta/models/$modCandidato:generateContent?key=$keyLimpia',
      );

      for (int intentoRed = 0; intentoRed < 4; intentoRed++) {
        await _asegurarRedDespierta();
        try {
          final res = await _httpClient
              .post(
                url,
                headers: {'Content-Type': 'application/json'},
                body: jsonEncode(payload),
              )
              .timeout(const Duration(seconds: 55));

          if (res.statusCode == 200) {
            final data = jsonDecode(res.body);
            final candidates = data['candidates'] as List? ?? [];
            if (candidates.isEmpty) {
              throw Exception('Gemini devolvio una respuesta vacia.');
            }
            final respParts =
                candidates[0]['content']['parts'] as List? ?? [];
            // Unir TODAS las partes de texto (excepto pensamientos internos) para que NUNCA quede cortada una respuesta larga
            final bufferRespuesta = StringBuffer();
            for (final p in respParts) {
              if (p is Map &&
                  p.containsKey('text') &&
                  p['thought'] != true) {
                bufferRespuesta.writeln(p['text'].toString());
              }
            }
            final textoCompleto = bufferRespuesta.toString().trim();
            final etiquetaFinal =
                (modInicial.contains('pro') && !modCandidato.contains('pro'))
                    ? '$modInicial (Turbo)'
                    : modCandidato;
            return {
              'texto': textoCompleto.isNotEmpty
                  ? textoCompleto
                  : respParts.last['text'].toString(),
              'modeloFinal': etiquetaFinal,
            };
          } else if (res.statusCode == 400 &&
              (payload['generationConfig'] as Map)
                  .containsKey('thinkingConfig')) {
            (payload['generationConfig'] as Map).remove('thinkingConfig');
            continue;
          } else if (res.statusCode == 429 || res.statusCode == 404) {
            _modelosSinCuotaEnSesion.add(modCandidato);
            ultimoDetalleError =
                'Codigo ${res.statusCode} ($modCandidato): ${res.body}';
            break;
          } else {
            ultimoDetalleError =
                'Codigo ${res.statusCode} ($modCandidato): ${res.body}';
            break;
          }
        } on SocketException catch (se) {
          ultimoDetalleError =
              'Reconectando red tras usar la camara (${se.message})...';
          await Future.delayed(Duration(seconds: 1 + intentoRed));
          continue;
        } on http.ClientException catch (ce) {
          ultimoDetalleError =
              'Reconectando cliente de red (${ce.message})...';
          await Future.delayed(Duration(seconds: 1 + intentoRed));
          continue;
        } catch (e) {
          ultimoDetalleError = e.toString();
          break;
        }
      }
    }

    throw Exception(ultimoDetalleError);
  }

  Future<List<String>> _descubrirModelosActivosEnCuenta(String apiKey) async {
    try {
      await _asegurarRedDespierta();
      final url = Uri.parse(
          'https://generativelanguage.googleapis.com/v1beta/models?key=$apiKey');
      final res =
          await _httpClient.get(url).timeout(const Duration(seconds: 12));
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body);
        final models = data['models'] as List? ?? [];
        final disponibles = <String>[];
        for (final m in models) {
          final name = (m['name'] as String? ?? '').replaceFirst('models/', '');
          final methods = (m['supportedGenerationMethods'] as List? ?? [])
              .map((e) => e.toString())
              .toList();
          if (methods.contains('generateContent') &&
              name.startsWith('gemini') &&
              !name.contains('embedding') &&
              !name.contains('imagen') &&
              !name.contains('tts')) {
            disponibles.add(name);
          }
        }
        return disponibles;
      }
    } catch (_) {}
    return [];
  }

